import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"Going to a Weekend Party","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/dialogues/03-weekend-party.md","filePath":"en/more/maltese/practice/dialogues/03-weekend-party.md"}'),r={name:"en/more/maltese/practice/dialogues/03-weekend-party.md"},n=d('<h1 id="going-to-a-weekend-party" tabindex="-1">Going to a Weekend Party <a class="header-anchor" href="#going-to-a-weekend-party" aria-label="Permalink to &quot;Going to a Weekend Party&quot;">​</a></h1><p><strong>Scenario:</strong> Two friends make plans for a weekend party.</p><h2 id="complete-dialogue" tabindex="-1">Complete Dialogue <a class="header-anchor" href="#complete-dialogue" aria-label="Permalink to &quot;Complete Dialogue&quot;">​</a></h2><p><strong>Anna:</strong> Se tagħmel xi ħaġa fi tmiem il-ġimgħa?</p><p><strong>Mark:</strong> Għadni ma ddeċidejtx. Għaliex?</p><p><strong>Anna:</strong> Qed norganizza festa d-dar is-Sibt filgħaxija.</p><p><strong>Mark:</strong> Ħsejjes sbieħ! F&#39;liema ħin tibda?</p><p><strong>Anna:</strong> Nibdew fit-tmienja, imma tista&#39; tasal aktar tard.</p><p><strong>Mark:</strong> X&#39;għandi nġib miegħi?</p><p><strong>Anna:</strong> Ġib xi ħaġa x&#39;tixorbu u jien nagħmel l-ikel.</p><p><strong>Mark:</strong> Perfett. Inkun hemm fit-tmienja.</p><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><h3 id="_1-anna" tabindex="-1">1. Anna <a class="header-anchor" href="#_1-anna" aria-label="Permalink to &quot;1. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Se tagħmel xi ħaġa fi tmiem il-ġimgħa?</p><p><strong>Translation:</strong> Are you doing anything this weekend?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Se</td><td>will; going to</td><td>Used with the imperfect to ask about plans</td></tr><tr><td>tagħmel</td><td>you do; you make</td><td>Second-person singular form</td></tr><tr><td>xi</td><td>some; any</td><td>Used to ask whether there are plans</td></tr><tr><td>ħaġa</td><td>thing</td><td>Feminine noun</td></tr><tr><td>fi</td><td>in; at</td><td>Preposition used with time expressions</td></tr><tr><td>tmiem</td><td>end</td><td>Masculine noun</td></tr><tr><td>il-ġimgħa</td><td>the week</td><td><code>tmiem il-ġimgħa</code> as a whole means “weekend”</td></tr></tbody></table><h3 id="_2-mark" tabindex="-1">2. Mark <a class="header-anchor" href="#_2-mark" aria-label="Permalink to &quot;2. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Għadni ma ddeċidejtx. Għaliex?</p><p><strong>Translation:</strong> I haven&#39;t decided yet. Why?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għadni</td><td>I still; I have yet to</td><td><code>għad</code> “still” + first-person suffix <code>-ni</code></td></tr><tr><td>ma</td><td>not</td><td>Part of the negative construction, commonly paired with final <code>x</code></td></tr><tr><td>ddeċidejtx</td><td>I did not decide; I haven&#39;t decided</td><td>Negative perfect form; final <code>-x</code> marks negation</td></tr><tr><td>Għaliex</td><td>why</td><td>Question word</td></tr></tbody></table><h3 id="_3-anna" tabindex="-1">3. Anna <a class="header-anchor" href="#_3-anna" aria-label="Permalink to &quot;3. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Qed norganizza festa d-dar is-Sibt filgħaxija.</p><p><strong>Translation:</strong> I&#39;m organizing a party at home on Saturday evening.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Qed</td><td>currently; in the process of</td><td>Combines with an imperfect verb to express an ongoing action</td></tr><tr><td>norganizza</td><td>I organize</td><td>First-person singular form</td></tr><tr><td>festa</td><td>party; celebration</td><td>Feminine noun</td></tr><tr><td>d-dar</td><td>at home; the house</td><td>Common contracted spelling of <code>id-dar</code></td></tr><tr><td>is-Sibt</td><td>Saturday</td><td>Often used with the definite article</td></tr><tr><td>filgħaxija</td><td>in the evening</td><td>Time expression</td></tr></tbody></table><h3 id="_4-mark" tabindex="-1">4. Mark <a class="header-anchor" href="#_4-mark" aria-label="Permalink to &quot;4. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Ħsejjes sbieħ! F&#39;liema ħin tibda?</p><p><strong>Translation:</strong> Sounds nice! What time does it start?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ħsejjes</td><td>it sounds</td><td>Third-person form, related literally to “sounds”</td></tr><tr><td>sbieħ</td><td>nice; pleasant</td><td>Masculine plural form/fixed expression</td></tr><tr><td>F&#39;liema</td><td>at what; in which</td><td><code>f&#39;</code> “at” + <code>liema</code> “which/what”</td></tr><tr><td>ħin</td><td>time</td><td>Masculine noun</td></tr><tr><td>tibda</td><td>you start; it starts</td><td>The form depends on the subject; here it refers to the party</td></tr></tbody></table><h3 id="_5-anna" tabindex="-1">5. Anna <a class="header-anchor" href="#_5-anna" aria-label="Permalink to &quot;5. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Nibdew fit-tmienja, imma tista&#39; tasal aktar tard.</p><p><strong>Translation:</strong> We&#39;ll start at eight, but you can arrive later.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nibdew</td><td>we start</td><td>First-person plural form</td></tr><tr><td>fit-tmienja</td><td>at eight</td><td>Contracted <code>f&#39;</code> + definite clock-hour form</td></tr><tr><td>imma</td><td>but</td><td>Conjunction</td></tr><tr><td>tista&#39;</td><td>you can</td><td>Second-person singular form</td></tr><tr><td>tasal</td><td>you arrive</td><td>Second-person singular form</td></tr><tr><td>aktar</td><td>more; later</td><td>Comparative adverb</td></tr><tr><td>tard</td><td>late</td><td>Adverb/adjective</td></tr></tbody></table><h3 id="_6-mark" tabindex="-1">6. Mark <a class="header-anchor" href="#_6-mark" aria-label="Permalink to &quot;6. Mark&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;għandi nġib miegħi?</p><p><strong>Translation:</strong> What should I bring with me?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>X&#39;</td><td>what</td><td>Shortened question word</td></tr><tr><td>għandi</td><td>I have; should I</td><td>With the following verb, it expresses “what should I…”</td></tr><tr><td>nġib</td><td>I bring</td><td>First-person singular form</td></tr><tr><td>miegħi</td><td>with me; along with me</td><td><code>miegħ</code> “with” + <code>-i</code> “me”</td></tr></tbody></table><h3 id="_7-anna" tabindex="-1">7. Anna <a class="header-anchor" href="#_7-anna" aria-label="Permalink to &quot;7. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Ġib xi ħaġa x&#39;tixorbu u jien nagħmel l-ikel.</p><p><strong>Translation:</strong> Bring something to drink, and I&#39;ll prepare the food.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ġib</td><td>bring</td><td>Singular imperative</td></tr><tr><td>xi</td><td>some</td><td>Indefinite determiner</td></tr><tr><td>ħaġa</td><td>thing</td><td>Feminine noun</td></tr><tr><td>x&#39;</td><td>to; that can be</td><td>Introduces a clause describing the preceding noun</td></tr><tr><td>tixorbu</td><td>you drink (plural); everyone drinks</td><td>Plural form, referring here to the guests</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>jien</td><td>I</td><td>Emphatic pronoun</td></tr><tr><td>nagħmel</td><td>I do; I make; I prepare</td><td>First-person singular form</td></tr><tr><td>l-ikel</td><td>the food</td><td>Definite article + <code>ikel</code></td></tr></tbody></table><h3 id="_8-mark" tabindex="-1">8. Mark <a class="header-anchor" href="#_8-mark" aria-label="Permalink to &quot;8. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Perfett. Inkun hemm fit-tmienja.</p><p><strong>Translation:</strong> Perfect. I&#39;ll be there at eight.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Perfett</td><td>perfect; great</td><td>Masculine adjective, also used as an exclamation</td></tr><tr><td>Inkun</td><td>I will be</td><td>First-person singular form</td></tr><tr><td>hemm</td><td>there; present</td><td>Place adverb</td></tr><tr><td>fit-tmienja</td><td>at eight</td><td>Time expression</td></tr></tbody></table><h2 id="conversational-alternatives" tabindex="-1">Conversational Alternatives <a class="header-anchor" href="#conversational-alternatives" aria-label="Permalink to &quot;Conversational Alternatives&quot;">​</a></h2><ul><li><code>il-Ġimgħa filgħaxija</code>: Friday evening.</li><li><code>Nista&#39; nġib deżerta?</code>: Can I bring dessert?</li><li><code>Narawk is-Sibt.</code>: See you on Saturday.</li></ul>',46),i=[n];function o(s,l,h,g,m,c){return e(),a("div",null,i)}const b=t(r,[["render",o]]);export{u as __pageData,b as default};
